def solve(grid):
    h = len(grid)
    w = len(grid[0])

    # Find the grid-line color (the non-zero dominant color)
    counts = {}
    for row in grid:
        for v in row:
            if v != 0:
                counts[v] = counts.get(v, 0) + 1
    line_color = max(counts, key=counts.get)

    # Separator rows/cols are those dominated by the line color
    sep_rows = [r for r in range(h) if sum(1 for x in grid[r] if x == line_color) >= w // 2]
    sep_cols = [c for c in range(w) if sum(1 for r in range(h) if grid[r][c] == line_color) >= h // 2]

    # Cell row/col bands between separator rows/cols
    row_bands = []
    start = 0
    for r in sep_rows:
        if start <= r - 1:
            row_bands.append((start, r - 1))
        start = r + 1
    if start <= h - 1:
        row_bands.append((start, h - 1))

    col_bands = []
    start = 0
    for c in sep_cols:
        if start <= c - 1:
            col_bands.append((start, c - 1))
        start = c + 1
    if start <= w - 1:
        col_bands.append((start, w - 1))

    nr = len(row_bands)
    nc = len(col_bands)

    # Build adjacency between cells through broken separator segments
    adj = {(i, j): [] for i in range(nr) for j in range(nc)}

    # Horizontal separators: connect vertically adjacent cells if that segment has any zero
    for si, r in enumerate(sep_rows):
        if si >= nr:
            break
        for j, (c1, c2) in enumerate(col_bands):
            if any(grid[r][c] == 0 for c in range(c1, c2 + 1)):
                a = (si, j)
                b = (si + 1, j)
                if b in adj:
                    adj[a].append(b)
                    adj[b].append(a)

    # Vertical separators: connect horizontally adjacent cells if that segment has any zero
    for sj, c in enumerate(sep_cols):
        if sj >= nc:
            break
        for i, (r1, r2) in enumerate(row_bands):
            if any(grid[r][c] == 0 for r in range(r1, r2 + 1)):
                a = (i, sj)
                b = (i, sj + 1)
                if b in adj:
                    adj[a].append(b)
                    adj[b].append(a)

    # Connected components of cells
    comp_id = {}
    comps = []
    for cell in adj:
        if cell in comp_id:
            continue
        stack = [cell]
        cid = len(comps)
        comp = []
        comp_id[cell] = cid
        while stack:
            cur = stack.pop()
            comp.append(cur)
            for nb in adj[cur]:
                if nb not in comp_id:
                    comp_id[nb] = cid
                    stack.append(nb)
        comps.append(comp)

    # Heuristic coloring:
    # components touching the outer border get color 3, internal ones get color 4.
    comp_color = {}
    for cid, comp in enumerate(comps):
        touch_border = False
        for i, j in comp:
            if i == 0 or i == nr - 1 or j == 0 or j == nc - 1:
                touch_border = True
                break
        comp_color[cid] = 3 if touch_border else 4

    # Paint output
    out = [row[:] for row in grid]
    for i, (r1, r2) in enumerate(row_bands):
        for j, (c1, c2) in enumerate(col_bands):
            color = comp_color[comp_id[(i, j)]]
            for r in range(r1, r2 + 1):
                for c in range(c1, c2 + 1):
                    if out[r][c] == 0:
                        out[r][c] = color

    return out

